<script>
const slides=[...document.querySelectorAll('.gallery-slide')],thumbs=[...document.querySelectorAll('.gallery-thumb')];let galleryIndex=0;
function showSlide(index){if(!slides.length)return;galleryIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('active',i===galleryIndex));thumbs.forEach((thumb,i)=>thumb.classList.toggle('active',i===galleryIndex));const activeSlide=slides[galleryIndex],stage=document.querySelector('.gallery-stage'),current=document.getElementById('gallery-current'),lightboxCurrent=document.getElementById('lightbox-current'),lightboxImage=document.getElementById('lightbox-image');stage?.style.setProperty('--gallery-backdrop',`url("${activeSlide.src.replace(/"/g,'\\"')}")`);if(current)current.textContent=galleryIndex+1;if(lightboxCurrent)lightboxCurrent.textContent=galleryIndex+1;if(lightboxImage)lightboxImage.src=activeSlide.src;thumbs[galleryIndex]?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
showSlide(0);
document.querySelector('.gallery-prev')?.addEventListener('click',()=>showSlide(galleryIndex-1));document.querySelector('.gallery-next')?.addEventListener('click',()=>showSlide(galleryIndex+1));thumbs.forEach((thumb,index)=>thumb.addEventListener('click',()=>showSlide(index)));document.querySelector('.gallery-stage')?.addEventListener('keydown',event=>{if(event.key==='ArrowRight')showSlide(galleryIndex-1);if(event.key==='ArrowLeft')showSlide(galleryIndex+1)});const lightbox=document.getElementById('gallery-lightbox');document.getElementById('gallery-expand')?.addEventListener('click',()=>{showSlide(galleryIndex);lightbox.showModal()});document.querySelector('.lightbox-close')?.addEventListener('click',()=>lightbox.close());document.querySelector('.lightbox-prev')?.addEventListener('click',()=>showSlide(galleryIndex-1));document.querySelector('.lightbox-next')?.addEventListener('click',()=>showSlide(galleryIndex+1));lightbox?.addEventListener('click',event=>{if(event.target===lightbox)lightbox.close()});let touchStart=0;document.querySelector('.gallery-stage')?.addEventListener('touchstart',event=>touchStart=event.changedTouches[0].clientX,{passive:true});document.querySelector('.gallery-stage')?.addEventListener('touchend',event=>{const delta=event.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>45)showSlide(galleryIndex+(delta>0?-1:1))},{passive:true});
const favoriteKey='ozman_real_estate_favorites',propertyId={{ $property->id }},fav=document.getElementById('favorite');function favoriteIds(){try{return JSON.parse(localStorage.getItem(favoriteKey)||'[]').map(Number)}catch(e){return[]}}function paintFavorite(){const on=favoriteIds().includes(propertyId);fav.textContent=(on?'♥ ':'♡ ')+'{{ $labels['favorite'] }}';fav.style.color=on?'#ff718c':''}fav.onclick=()=>{let ids=favoriteIds();ids=ids.includes(propertyId)?ids.filter(i=>i!==propertyId):[...ids,propertyId];localStorage.setItem(favoriteKey,JSON.stringify(ids));paintFavorite()};paintFavorite();
document.getElementById('share').onclick=async()=>{const data={title:@json($shareTitle),text:@json($shareDescription),url:location.href};if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(@json($shareText));alert('تم نسخ مواصفات العقار والرابط')}};
@if($property->purpose==='sale')function calculate(){const price={{ (float)$property->price }},down=Number(document.getElementById('down').value||0),years=Number(document.getElementById('years').value||1),annual=Number(document.getElementById('interest').value||0)/100,principal=Math.max(0,price-down),months=years*12,rate=annual/12;const payment=rate?principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):principal/months;document.getElementById('calculation').textContent='{{ $labels['monthly'] }}: '+Math.round(payment).toLocaleString()+' {{ $property->currency }}'}document.querySelectorAll('.calculator input').forEach(i=>i.oninput=calculate);calculate();@endif
@if($property->latitude&&$property->longitude)
if(window.L){const destination=[{{ $property->latitude }},{{ $property->longitude }}],map=L.map('property-map').setView(destination,15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);L.marker(destination).addTo(map).bindPopup(@json($title)).openPopup();const result=document.getElementById('distance-result'),button=document.getElementById('calculate-distance');button?.addEventListener('click',()=>{if(!navigator.geolocation){result.textContent='متصفحك لا يدعم تحديد الموقع.';return}button.disabled=true;result.textContent='جاري تحديد موقعك...';navigator.geolocation.getCurrentPosition(position=>{const origin=[position.coords.latitude,position.coords.longitude],toRad=value=>value*Math.PI/180,dLat=toRad(destination[0]-origin[0]),dLng=toRad(destination[1]-origin[1]),a=Math.sin(dLat/2)**2+Math.cos(toRad(origin[0]))*Math.cos(toRad(destination[0]))*Math.sin(dLng/2)**2,distance=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));L.marker(origin).addTo(map).bindPopup('موقعك الحالي');L.polyline([origin,destination],{color:'#16d9f3',weight:4,dashArray:'8 8'}).addTo(map);map.fitBounds([origin,destination],{padding:[35,35]});result.classList.add('ready');result.innerHTML=`المسافة المباشرة: <strong>${distance<1?Math.round(distance*1000)+' متر':distance.toFixed(1)+' كم'}</strong> · <a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&origin=${origin[0]},${origin[1]}&destination=${destination[0]},${destination[1]}">فتح مسار القيادة</a>`;button.disabled=false},()=>{result.textContent='تعذر تحديد موقعك. فعّل إذن الموقع للمتصفح، ويجب فتح الصفحة عبر HTTPS.';button.disabled=false},{enableHighAccuracy:true,timeout:12000})})}
@endif
</script></body></html>
